// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 delta) public {
        vm.assume(caller != address(0));
        delta = bound(delta, 1, 1000000);

        vm.deal(caller, 20 ether);

        uint256 initialTime = block.timestamp;
        vm.warp(initialTime + delta);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
